import React from 'react';

const AdminLoading = ({
  fullScreen = false,
  label = 'Loading data...',
  compact = false,
}) => {
  if (compact) {
    return (
      <div className="flex min-h-[220px] items-center justify-center p-6" role="status" aria-live="polite">
        <div className="text-center">
          <div className="relative mx-auto h-11 w-11 flex items-center justify-center">
            <div className="absolute inset-0 rounded-full border-3 border-blue-100 animate-ping opacity-25" />
            <div className="h-10 w-10 animate-spin rounded-full border-3 border-blue-100 border-t-blue-900" />
          </div>
          <p className="mt-3.5 text-xs font-semibold text-slate-500 tracking-wide">{label}</p>
        </div>
      </div>
    );
  }

  return (
    <div
      className={`${fullScreen ? 'fixed inset-0 z-[100]' : 'absolute inset-0 z-30'} flex items-center justify-center bg-[#F4F7FB]/90 backdrop-blur-sm transition-all duration-300`}
      role="status"
      aria-live="polite"
    >
      <div className="text-center bg-white p-7 rounded-2xl shadow-xl border border-slate-100 flex flex-col items-center">
        <div className="relative h-14 w-14 flex items-center justify-center">
          <div className="absolute inset-0 rounded-full border-4 border-blue-100 animate-ping opacity-20" />
          <div className="h-12 w-12 animate-spin rounded-full border-3 border-blue-100 border-t-blue-900" />
        </div>
        <p className="mt-4 text-xs sm:text-sm font-bold text-slate-700">{label}</p>
        <span className="mt-1 text-[11px] text-slate-400 font-medium">Please wait a moment...</span>
      </div>
    </div>
  );
};

export default AdminLoading;
